353	void ASTColumnsReplaceTransformer::transform(ASTs & nodes) const
354	{
355	    std::map<String, ASTPtr> replace_map;
356	    for (const auto & replace_child : children)
357	    {
358	        auto & replacement = replace_child->as<Replacement &>();
359	        if (replace_map.find(replacement.name) != replace_map.end())
360	            throw Exception(
361	                "Expressions in columns transformer REPLACE should not contain the same replacement more than once",
362	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
363	        replace_map.emplace(replacement.name, replacement.expr);
364	    }
365	
366	    for (auto & column : nodes)
367	    {
368	        if (const auto * id = column->as<ASTIdentifier>())
369	        {
370	            auto replace_it = replace_map.find(id->shortName());
371	            if (replace_it != replace_map.end())
372	            {
373	                column = replace_it->second;
374	                column->setAlias(replace_it->first);
375	                replace_map.erase(replace_it);
376	            }
377	        }
378	        else if (auto * ast_with_alias = dynamic_cast<ASTWithAlias *>(column.get()))
379	        {
380	            auto replace_it = replace_map.find(ast_with_alias->alias);
381	            if (replace_it != replace_map.end())
382	            {
383	                auto new_ast = replace_it->second->clone();
384	                ast_with_alias->alias = ""; // remove the old alias as it's useless after replace transformation
385	                replaceChildren(new_ast, column, replace_it->first);
386	                column = new_ast;
387	                column->setAlias(replace_it->first);
388	                replace_map.erase(replace_it);
389	            }
390	        }
391	    }
392	
393	    if (is_strict && !replace_map.empty())
394	    {
395	        String expected_columns;
396	        for (auto & elem: replace_map)
397	        {
398	            if (!expected_columns.empty())
399	                expected_columns += ", ";
400	            expected_columns += elem.first;
401	        }
402	        throw Exception(
403	            "Columns transformer REPLACE expects following column(s) : " + expected_columns,
404	            ErrorCodes::NO_SUCH_COLUMN_IN_TABLE);
405	    }
